-- Journal peer-review bounded context. Submitted manuscripts remain private.
CREATE TYPE "JournalStatus" AS ENUM ('DRAFT','ACTIVE','ARCHIVED');
CREATE TYPE "JournalMemberRole" AS ENUM ('OWNER','EDITOR','REVIEWER');
CREATE TYPE "SubmissionStatus" AS ENUM ('DRAFT','SUBMITTED','TECHNICAL_CHECK','EDITORIAL_SCREENING','UNDER_REVIEW','REVISION_REQUIRED','RESUBMITTED','ACCEPTED','REJECTED','WITHDRAWN','PUBLISHED','CORRECTED','RETRACTED');
CREATE TYPE "ReviewAssignmentStatus" AS ENUM ('INVITED','ACCEPTED','DECLINED','CONFLICT_DECLARED','IN_PROGRESS','SUBMITTED','EXPIRED','CANCELLED');
CREATE TYPE "ReviewRecommendation" AS ENUM ('ACCEPT','MINOR_REVISION','MAJOR_REVISION','REJECT');
CREATE TYPE "EditorialDecisionType" AS ENUM ('DESK_REJECT','REJECT','MINOR_REVISION','MAJOR_REVISION','ACCEPT');
CREATE TYPE "SubmissionFileScanStatus" AS ENUM ('PENDING','CLEAN','REJECTED');

CREATE TABLE "Journal" ("id" UUID NOT NULL,"slug" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT,"status" "JournalStatus" NOT NULL DEFAULT 'DRAFT',"ownerId" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Journal_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Journal_slug_key" ON "Journal"("slug"); CREATE INDEX "Journal_ownerId_idx" ON "Journal"("ownerId"); CREATE INDEX "Journal_status_idx" ON "Journal"("status");
CREATE TABLE "JournalMember" ("journalId" UUID NOT NULL,"userId" UUID NOT NULL,"role" "JournalMemberRole" NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "JournalMember_pkey" PRIMARY KEY ("journalId","userId"));
CREATE INDEX "JournalMember_userId_idx" ON "JournalMember"("userId");
CREATE TABLE "Submission" ("id" UUID NOT NULL,"journalId" UUID NOT NULL,"submittingAuthorId" UUID NOT NULL,"title" TEXT NOT NULL,"abstract" TEXT,"status" "SubmissionStatus" NOT NULL DEFAULT 'DRAFT',"currentVersionId" UUID,"reviewRound" INTEGER NOT NULL DEFAULT 0,"submittedAt" TIMESTAMP(3),"decidedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Submission_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Submission_journalId_status_updatedAt_idx" ON "Submission"("journalId","status","updatedAt"); CREATE INDEX "Submission_submittingAuthorId_status_idx" ON "Submission"("submittingAuthorId","status");
CREATE TABLE "SubmissionAuthor" ("submissionId" UUID NOT NULL,"userId" UUID NOT NULL,"authorOrder" INTEGER NOT NULL,"corresponding" BOOLEAN NOT NULL DEFAULT false,CONSTRAINT "SubmissionAuthor_pkey" PRIMARY KEY ("submissionId","userId")); CREATE INDEX "SubmissionAuthor_userId_idx" ON "SubmissionAuthor"("userId");
CREATE TABLE "SubmissionVersion" ("id" UUID NOT NULL,"submissionId" UUID NOT NULL,"versionNumber" INTEGER NOT NULL,"title" TEXT NOT NULL,"abstract" TEXT,"createdById" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SubmissionVersion_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "SubmissionVersion_submissionId_versionNumber_key" ON "SubmissionVersion"("submissionId","versionNumber");
CREATE TABLE "SubmissionFile" ("id" UUID NOT NULL,"versionId" UUID NOT NULL,"storageKey" TEXT NOT NULL,"originalName" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"sizeBytes" INTEGER NOT NULL,"sha256" TEXT NOT NULL,"scanStatus" "SubmissionFileScanStatus" NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SubmissionFile_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "SubmissionFile_storageKey_key" ON "SubmissionFile"("storageKey");
CREATE TABLE "ReviewerAssignment" ("id" UUID NOT NULL,"submissionId" UUID NOT NULL,"versionId" UUID NOT NULL,"reviewerId" UUID NOT NULL,"assignedById" UUID NOT NULL,"status" "ReviewAssignmentStatus" NOT NULL DEFAULT 'INVITED',"dueAt" TIMESTAMP(3) NOT NULL,"conflictNote" TEXT,"invitedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"respondedAt" TIMESTAMP(3),CONSTRAINT "ReviewerAssignment_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "ReviewerAssignment_versionId_reviewerId_key" ON "ReviewerAssignment"("versionId","reviewerId");
CREATE TABLE "Review" ("id" UUID NOT NULL,"assignmentId" UUID NOT NULL,"versionId" UUID NOT NULL,"reviewerId" UUID NOT NULL,"recommendation" "ReviewRecommendation" NOT NULL,"publicComments" TEXT NOT NULL,"confidentialComments" TEXT,"submittedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Review_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Review_assignmentId_key" ON "Review"("assignmentId");
CREATE TABLE "EditorialDecision" ("id" UUID NOT NULL,"submissionId" UUID NOT NULL,"versionId" UUID NOT NULL,"editorId" UUID NOT NULL,"decision" "EditorialDecisionType" NOT NULL,"reason" TEXT NOT NULL,"round" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "EditorialDecision_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "EditorialDecision_versionId_round_key" ON "EditorialDecision"("versionId","round");
CREATE TABLE "SubmissionStatusHistory" ("id" UUID NOT NULL,"submissionId" UUID NOT NULL,"fromStatus" "SubmissionStatus","toStatus" "SubmissionStatus" NOT NULL,"actorId" UUID,"note" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SubmissionStatusHistory_pkey" PRIMARY KEY ("id"));

ALTER TABLE "Journal" ADD CONSTRAINT "Journal_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "JournalMember" ADD CONSTRAINT "JournalMember_journalId_fkey" FOREIGN KEY ("journalId") REFERENCES "Journal"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "JournalMember" ADD CONSTRAINT "JournalMember_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Submission" ADD CONSTRAINT "Submission_journalId_fkey" FOREIGN KEY ("journalId") REFERENCES "Journal"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Submission" ADD CONSTRAINT "Submission_submittingAuthorId_fkey" FOREIGN KEY ("submittingAuthorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SubmissionAuthor" ADD CONSTRAINT "SubmissionAuthor_submissionId_fkey" FOREIGN KEY ("submissionId") REFERENCES "Submission"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SubmissionAuthor" ADD CONSTRAINT "SubmissionAuthor_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SubmissionVersion" ADD CONSTRAINT "SubmissionVersion_submissionId_fkey" FOREIGN KEY ("submissionId") REFERENCES "Submission"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "SubmissionVersion" ADD CONSTRAINT "SubmissionVersion_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SubmissionFile" ADD CONSTRAINT "SubmissionFile_versionId_fkey" FOREIGN KEY ("versionId") REFERENCES "SubmissionVersion"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ReviewerAssignment" ADD CONSTRAINT "ReviewerAssignment_submissionId_fkey" FOREIGN KEY ("submissionId") REFERENCES "Submission"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ReviewerAssignment" ADD CONSTRAINT "ReviewerAssignment_versionId_fkey" FOREIGN KEY ("versionId") REFERENCES "SubmissionVersion"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ReviewerAssignment" ADD CONSTRAINT "ReviewerAssignment_reviewerId_fkey" FOREIGN KEY ("reviewerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "ReviewerAssignment" ADD CONSTRAINT "ReviewerAssignment_assignedById_fkey" FOREIGN KEY ("assignedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Review" ADD CONSTRAINT "Review_assignmentId_fkey" FOREIGN KEY ("assignmentId") REFERENCES "ReviewerAssignment"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Review" ADD CONSTRAINT "Review_versionId_fkey" FOREIGN KEY ("versionId") REFERENCES "SubmissionVersion"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Review" ADD CONSTRAINT "Review_reviewerId_fkey" FOREIGN KEY ("reviewerId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "EditorialDecision" ADD CONSTRAINT "EditorialDecision_submissionId_fkey" FOREIGN KEY ("submissionId") REFERENCES "Submission"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "EditorialDecision" ADD CONSTRAINT "EditorialDecision_versionId_fkey" FOREIGN KEY ("versionId") REFERENCES "SubmissionVersion"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "EditorialDecision" ADD CONSTRAINT "EditorialDecision_editorId_fkey" FOREIGN KEY ("editorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SubmissionStatusHistory" ADD CONSTRAINT "SubmissionStatusHistory_submissionId_fkey" FOREIGN KEY ("submissionId") REFERENCES "Submission"("id") ON DELETE CASCADE ON UPDATE CASCADE;
